const CHAPTERS = {
  1: "The values and principles of the UK",
  2: "What is the UK?",
  3: "A long and illustrious history",
  4: "A modern, thriving society",
  5: "The UK government, the law and your role",
};
const STUDY = [
{id:1,ch:1,d:1,src:["1.0","6.0","7.0","9.4","15.7"],en:"As a British citizen or permanent resident you should: respect and obey the law; respect the rights of others (including their right to their own opinions); treat others with fairness; look after yourself and your family; look after the area in which you live and the environment; and pay taxes.",yue:"作為英國公民或永久居民嘅責任：遵守法律、尊重他人權利同意見、公平待人、照顧自己同家人、照顧居住環境，同埋交稅。"},
{id:2,ch:1,d:2,src:["3.0","5.4","6.12","8.9"],en:"The five fundamental principles of British life are: democracy, the rule of law, individual liberty, tolerance of those with different faiths and beliefs, and participation in community life. Monarchy is NOT one of them.",yue:"英國生活五大基本原則：民主、法治、個人自由、寬容不同信仰、參與社區生活。「君主制」唔係其中之一。"},
{id:3,ch:2,d:4,src:["4.6","6.5","17.8"],geo:["UK","region"],en:"The UK is made up of England, Scotland, Wales and Northern Ireland. \"Great Britain\" refers only to England, Scotland and Wales (not Northern Ireland).",yue:"英國（UK）由 England（英格蘭）、Scotland（蘇格蘭）、Wales（威爾斯）同 Northern Ireland（北愛爾蘭）組成。「Great Britain（大不列顛）」只包括 England、Scotland、Wales，唔包括北愛爾蘭。"},
{id:4,ch:2,d:5,src:["1.19","5.19","12.0","17.5"],geo:["UK","region"],en:"The Channel Islands (e.g. Jersey) and the Isle of Man are Crown dependencies: closely linked to the UK, with their own governments, but NOT part of the UK.",yue:"Channel Islands（如 Jersey（澤西島））同 Isle of Man（曼島）係 Crown dependencies（皇家屬地）：同英國關係密切、有自己政府，但唔係英國一部分。"},
{id:5,ch:2,d:5,src:["2.1","5.3","11.0"],geo:["UK","region"],en:"St Helena and the Falkland Islands are British overseas territories: linked to the UK but not part of it (and not part of Great Britain).",yue:"St Helena（聖赫勒拿島）同 Falkland Islands（福克蘭群島）係英國海外領土：同英國有聯繫，但唔屬於英國或 Great Britain（大不列顛）。"},
{id:6,ch:2,d:1,src:["1.3"],geo:["UK","region"],en:"The UK is located in the north-west of Europe.",yue:"英國位於歐洲西北部。"},
{id:7,ch:3,d:3,src:["2.6","15.4"],y:-4000,yl:"c. 4000 BC",en:"The first farmers came to Britain about 6,000 years ago, probably from south-east Europe.",yue:"第一批農民約 6,000 年前來到英國，可能來自東南歐。"},
{id:8,ch:3,d:3,src:["14.18"],y:-3000,yl:"c. 3000 BC",geo:["England","landmark"],en:"Stonehenge, in Wiltshire (England), is a Stone Age monument built about 5,000 years ago.",yue:"Stonehenge（巨石陣）喺英格蘭 Wiltshire（威爾特郡），係約 5,000 年前嘅石器時代遺跡。"},
{id:9,ch:3,d:4,src:["6.1","12.4"],y:-100,yl:"Iron Age",en:"The first coins minted in Britain were made in the Iron Age; some carried the names of Iron Age kings.",yue:"英國最早嘅硬幣喺鐵器時代鑄造，部分刻有鐵器時代國王嘅名。"},
{id:10,ch:3,d:4,src:["2.9"],y:-55,yl:"55 BC",w:1,p:["Julius Caesar","monarch"],en:"Julius Caesar led the first Roman invasion of Britain in 55 BC, which failed. The Romans conquered Britain under Emperor Claudius in AD 43.",yue:"Julius Caesar（凱撒）喺公元前 55 年帶領羅馬首次入侵英國，未成功；公元 43 年 Claudius（克勞狄烏斯）皇帝先成功佔領。"},
{id:11,ch:3,d:3,src:["13.2"],y:60,yl:"AD 60",w:1,p:["Boudicca","monarch"],en:"Boudicca, queen of the Iceni tribe, led a revolt against the Romans (around AD 60).",yue:"Boudicca（布狄卡）係 Iceni（愛西尼）部族女王，約公元 60 年率眾反抗羅馬人。"},
{id:12,ch:3,d:3,src:["2.18","16.15"],y:122,yl:"AD 122",geo:["England","landmark"],en:"Hadrian's Wall was built by the Romans (AD 122) across northern England to mark the northern boundary of their empire in Britain.",yue:"Hadrian's Wall（哈德良長城）由羅馬人喺公元 122 年建造，橫跨英格蘭北部，標示羅馬帝國喺英國嘅北界。"},
{id:13,ch:3,d:4,src:["16.3"],y:410,yl:"AD 410",en:"The Romans left Britain in AD 410. Tribes from northern Europe — the Jutes, Angles and Saxons — then settled in Britain.",yue:"羅馬人喺公元 410 年撤離英國，之後北歐部族 Jutes（朱特人）、Angles（盎格魯人）同 Saxons（撒克遜人）移居英國。"},
{id:14,ch:3,d:3,src:["17.14"],y:850,yl:"9th–10th century",w:1,en:"The Vikings came from Denmark and Norway in the 9th and 10th centuries, using longships to trade and to raid. They invaded and settled in England.",yue:"Vikings（維京人）喺 9 至 10 世紀由丹麥同挪威而來，用 longships（長船）貿易同掠奪，並入侵及定居英格蘭。"},
{id:15,ch:3,d:3,src:["2.10"],y:878,yl:"AD 878",w:1,p:["Alfred the Great","monarch"],en:"King Alfred the Great united the Anglo-Saxon kingdoms to defeat the Vikings.",yue:"King Alfred the Great（阿佛烈大帝）統一盎格魯－撒克遜各王國，打敗 Vikings（維京人）。"},
{id:16,ch:3,d:1,src:["4.17","6.18","9.20","17.17"],y:1066,w:1,p:["William the Conqueror","monarch"],en:"In 1066 William, Duke of Normandy (the Normans were descendants of Vikings who had settled in northern France), defeated King Harold at the Battle of Hastings — the Norman Conquest of England.",yue:"1066 年 Normandy（諾曼第）公爵 William（Normans 係定居法國北部嘅 Viking 後裔）喺 Battle of Hastings（黑斯廷斯戰役）打敗 King Harold（哈羅德國王），史稱 Norman Conquest（諾曼征服）。"},
{id:17,ch:3,d:3,src:["17.19","15.0"],en:"After the Norman Conquest a new ruling class, a new legal system and castles came to England. In the Middle Ages the nobility spoke Norman French while the peasants spoke Anglo-Saxon.",yue:"Norman Conquest（諾曼征服）之後英格蘭有新統治階層、新法律制度同城堡。中世紀貴族講 Norman French（諾曼法語），農民講 Anglo-Saxon（盎格魯撒克遜語）。"},
{id:18,ch:3,d:2,src:["11.16","16.9"],en:"The Bayeux Tapestry is an embroidery that depicts the Norman Conquest of England in 1066.",yue:"Bayeux Tapestry（貝葉掛毯）係一幅刺繡，描繪 1066 年 Norman Conquest（諾曼征服）。"},
{id:19,ch:3,d:3,src:["6.2"],geo:["England","landmark"],en:"The Tower of London was built by William the Conqueror after the Norman Conquest.",yue:"Tower of London（倫敦塔）由 William the Conqueror（征服者威廉）喺 Norman Conquest（諾曼征服）後建造。"},
{id:20,ch:3,d:3,src:["4.13","10.7","13.6"],y:1086,en:"The Domesday Book (1086), commissioned by William the Conqueror, was a survey recording who owned land and what property existed in England.",yue:"Domesday Book（1086 年）由 William the Conqueror（征服者威廉）下令編製，記錄英格蘭土地同財產嘅擁有者。"},
{id:21,ch:3,d:1,src:["4.16","6.6","7.14","8.13","12.23","15.6","16.16","17.21"],y:1215,p:["King John","monarch"],en:"In 1215 King John signed the Magna Carta, which limited the power of the King and established that no one — not even the King — is above the law.",yue:"1215 年 King John（約翰王）簽署 Magna Carta（大憲章），限制國王權力，確立「無人凌駕法律之上，國王都唔例外」。"},
{id:22,ch:3,d:4,src:["7.5"],y:1314,w:1,p:["Robert the Bruce","monarch"],en:"In 1314 the Scots, led by Robert the Bruce, defeated the English at the Battle of Bannockburn, and Scotland remained independent.",yue:"1314 年 Robert the Bruce（羅伯特·布魯斯）率領蘇格蘭人喺 Battle of Bannockburn（班諾克本戰役）打敗英格蘭，蘇格蘭保持獨立。"},
{id:23,ch:3,d:4,src:["3.4","9.21"],y:1337,w:1,en:"The Hundred Years War between England and France (1337–1453) actually lasted 116 years.",yue:"Hundred Years War（百年戰爭）係英格蘭同法國之間嘅戰爭（1337–1453），實際持續 116 年。"},
{id:24,ch:3,d:3,src:["9.15","14.9"],y:1348,en:"The Black Death, a plague, arrived in England in 1348 and killed about one third of the population.",yue:"Black Death（黑死病）1348 年傳入英格蘭，約三分之一人口死亡。"},
{id:25,ch:3,d:3,src:["10.3","13.3"],p:["Geoffrey Chaucer","writer"],en:"Geoffrey Chaucer wrote The Canterbury Tales, a series of poems about a group of people going on a pilgrimage to Canterbury.",yue:"Geoffrey Chaucer（喬叟）寫咗 The Canterbury Tales（坎特伯雷故事集），講一班人去 Canterbury 朝聖嘅故事。"},
{id:26,ch:3,d:3,src:["1.5"],y:1455,w:1,en:"The Wars of the Roses (1455–1485) were fought between the House of York and the House of Lancaster. Henry VII (Tudor) won and united the two houses.",yue:"Wars of the Roses（1455–1485）係 House of York（約克家族）同 House of Lancaster（蘭開斯特家族）之間嘅內戰，最後 Henry VII（都鐸王朝）勝出並統一兩家。"},
{id:27,ch:3,d:2,src:["13.11","17.13"],p:["Henry VIII","monarch"],en:"Henry VIII had six wives; two were executed. His second wife, Anne Boleyn, was the mother of Elizabeth I.",yue:"Henry VIII（亨利八世）有 6 個妻子，其中 2 個被處決。第二任妻子 Anne Boleyn（安妮·博林）係 Elizabeth I（伊利沙伯一世）嘅母親。"},
{id:28,ch:3,d:3,src:["3.3","13.22","17.9"],y:1534,en:"The Reformation was a 16th-century movement that broke from the Catholic Church. Henry VIII established the Church of England (1534) because the Pope would not let him divorce his first wife, Catherine of Aragon.",yue:"Reformation（宗教改革）係 16 世紀脫離天主教會嘅運動。Henry VIII（亨利八世）因教宗唔准佢同第一任妻子 Catherine of Aragon（阿拉貢的凱瑟琳）離婚，於 1534 年成立 Church of England（英格蘭國教會）。"},
{id:29,ch:3,d:3,src:["2.13","8.23","12.8"],y:1536,en:"During the Reformation, Henry VIII closed the Catholic monasteries and seized their wealth — the Dissolution of the Monasteries.",yue:"Reformation（宗教改革）期間 Henry VIII（亨利八世）關閉天主教修道院並沒收財產，稱為 Dissolution of the Monasteries（解散修道院）。"},
{id:30,ch:3,d:3,src:["16.20","1.11"],y:1588,w:1,p:["Elizabeth I","monarch"],en:"Elizabeth I (reigned 1558–1603), daughter of Henry VIII, was a Protestant queen. In 1588 the English defeated the Spanish Armada.",yue:"Elizabeth I（1558–1603 在位）係 Henry VIII（亨利八世）嘅女兒，新教女王。1588 年英格蘭擊敗西班牙無敵艦隊（Spanish Armada）。"},
{id:31,ch:3,d:3,src:["3.21","8.5","16.2"],y:1587,p:["Mary, Queen of Scots","monarch"],en:"Mary, Queen of Scots was imprisoned by Elizabeth I for 20 years and then executed.",yue:"Mary, Queen of Scots（蘇格蘭女王瑪麗）被 Elizabeth I（伊利沙伯一世）囚禁 20 年，最後被處決。"},
{id:32,ch:3,d:1,src:["9.5","9.17","12.9","13.20"],p:["William Shakespeare","writer"],en:"William Shakespeare was born in Stratford-upon-Avon (and went to Stratford Grammar School). He wrote plays including Hamlet and A Midsummer Night's Dream.",yue:"William Shakespeare（莎士比亞）喺 Stratford-upon-Avon（埃文河畔斯特拉福）出生同讀書，作品包括 Hamlet（哈姆雷特）同 A Midsummer Night's Dream（仲夏夜之夢）。"},
{id:33,ch:3,d:3,src:["7.8"],y:1605,p:["Guy Fawkes","reformer"],en:"The Gunpowder Plot (1605) was a failed plot by Guy Fawkes and others to blow up Parliament and kill King James I.",yue:"Gunpowder Plot（1605 年）係 Guy Fawkes（蓋伊·福克斯）等人企圖炸毀國會、殺死 King James I（詹姆斯一世國王）嘅失敗陰謀。"},
{id:34,ch:3,d:4,src:["12.7"],y:1611,p:["James I","monarch"],en:"The version of the Bible created under King James I (1611) is known as the Authorised Version, or King James Bible.",yue:"King James I（詹姆斯一世國王）主持翻譯嘅聖經（1611 年）稱為 Authorised Version（欽定版聖經），又叫 King James Bible（詹姆斯王聖經）。"},
{id:35,ch:3,d:4,src:["16.10"],y:1628,en:"The Petition of Right (1628) confirmed that the King could not raise taxes without the consent of Parliament.",yue:"Petition of Right（1628 年）確認國王未經國會同意不得徵稅。"},
{id:36,ch:3,d:3,src:["11.18","15.12"],y:1642,w:1,p:["Charles I","monarch"],en:"The English Civil War (1642–1651) was fought between Parliament and King Charles I over who held power. Charles I was executed.",yue:"English Civil War（1642–1651）係國會同 King Charles I（查理一世國王）爭奪權力嘅內戰，Charles I 最終被處決。"},
{id:37,ch:3,d:3,src:["15.2"],y:1649,en:"After Charles I was executed in 1649, England was declared a republic (the Commonwealth) — the only period it was not ruled by a monarch.",yue:"1649 年 Charles I（查理一世）被處決後，英格蘭成為共和國（Commonwealth），係唯一冇君主統治嘅時期。"},
{id:38,ch:3,d:2,src:["1.22","15.19"],p:["Oliver Cromwell","politician"],en:"Oliver Cromwell led the Parliamentarians in the Civil War and was given the title Lord Protector (1649–1658).",yue:"Oliver Cromwell（克倫威爾）係內戰中國會派領袖，獲封 Lord Protector（1649–1658）。"},
{id:39,ch:3,d:4,src:["13.5"],p:["Charles II","monarch"],en:"After his defeat in the Civil War, Charles II escaped to Europe, famously hiding in an oak tree (the \"Royal Oak\").",yue:"Charles II（查理二世）內戰失敗後逃往歐洲，曾匿喺一棵橡樹入面（「Royal Oak」）。"},
{id:40,ch:3,d:3,src:["4.2","7.19","11.11"],y:1666,en:"The Great Fire of London (1666), during the reign of Charles II, destroyed much of the city including St Paul's Cathedral.",yue:"Great Fire of London（1666 年）發生喺 Charles II（查理二世）年代，燒毀大部分倫敦市區，包括 St Paul's Cathedral（聖保羅大教堂）。"},
{id:41,ch:3,d:4,src:["14.15"],p:["Samuel Pepys","writer"],en:"Samuel Pepys was a 17th-century diarist who wrote about the Great Fire of London.",yue:"Samuel Pepys（佩皮斯）係 17 世紀日記作家，記錄咗 Great Fire of London（倫敦大火）。"},
{id:42,ch:3,d:3,src:["7.7"],geo:["England","landmark"],p:["Sir Christopher Wren","artist"],en:"Sir Christopher Wren was the architect of St Paul's Cathedral, rebuilt after the Great Fire of London.",yue:"Sir Christopher Wren（基斯杜化·雷恩爵士）係 St Paul's Cathedral（聖保羅大教堂）嘅建築師，大火後重建。"},
{id:43,ch:3,d:4,src:["15.16"],y:1688,p:["William of Orange","monarch"],en:"In the Glorious Revolution (1688) James II was peacefully replaced by William of Orange, establishing constitutional monarchy.",yue:"Glorious Revolution（1688 年）James II（詹姆斯二世）被 William of Orange（奧蘭治的威廉）和平取代，奠定君主立憲制。"},
{id:44,ch:3,d:5,src:["1.6","7.2"],y:1689,en:"The Bill of Rights (1689) limited the power of the King and confirmed the rights of Parliament. It did NOT give anyone the right to vote.",yue:"Bill of Rights（1689 年）限制國王權力、確認國會權利，並冇賦予任何人投票權。"},
{id:45,ch:3,d:3,src:["10.8","12.14","13.17"],y:1707,en:"The Act of Union 1707 united the Parliaments of England and Scotland, creating the Kingdom of Great Britain.",yue:"Act of Union（聯合法案） 1707 合併英格蘭同蘇格蘭國會，成立 Kingdom of Great Britain（大不列顛王國）。"},
{id:46,ch:3,d:3,src:["10.23","11.23","14.2"],y:1721,p:["Sir Robert Walpole","politician"],en:"Sir Robert Walpole was the first Prime Minister (1721–1742).",yue:"Sir Robert Walpole（羅伯特·沃波爾爵士）係第一位首相（1721–1742）。"},
{id:47,ch:3,d:4,src:["3.5"],y:1745,w:1,p:["Bonnie Prince Charlie","monarch"],en:"In 1745 Bonnie Prince Charlie (Charles Edward Stuart) raised an army of Scottish Highland clansmen to try to regain the throne for the Stuarts; he was defeated at Culloden in 1746.",yue:"1745 年 Bonnie Prince Charlie（Charles Edward Stuart）召集蘇格蘭高地氏族起兵，企圖為 Stuart（斯圖亞特）王朝奪回王位，1746 年喺 Culloden（卡洛登）戰敗。"},
{id:48,ch:3,d:3,src:["11.4","14.4"],y:1750,yl:"18th century",p:["Adam Smith","scientist"],en:"The Enlightenment was an 18th-century period when new ideas about politics, philosophy and science developed. Adam Smith developed ideas about economics.",yue:"Enlightenment（啟蒙時代）係 18 世紀政治、哲學同科學新思想蓬勃嘅時期；Adam Smith（亞當·斯密）提出經濟學理論。"},
{id:49,ch:3,d:5,src:["4.7","8.11","8.21"],p:["Isaac Newton","scientist"],en:"Isaac Newton, born in Woolsthorpe, Lincolnshire, discovered the laws of gravity and motion. He was later Warden and then Master of the Royal Mint.",yue:"Isaac Newton（牛頓）喺 Lincolnshire（林肯郡）嘅 Woolsthorpe（伍爾索普）出生，發現萬有引力同運動定律，後來出任 Royal Mint（皇家鑄幣廠）嘅 Warden（監督）同 Master（總監）。"},
{id:50,ch:3,d:2,src:["2.14","16.17"],p:["Robert Burns","writer"],en:"Robert Burns is Scotland's national poet; he wrote Auld Lang Syne. Burns Night is celebrated on 25th January.",yue:"Robert Burns（羅伯特·彭斯）係蘇格蘭民族詩人，寫咗 Auld Lang Syne（友誼萬歲）；1 月 25 日係 Burns Night（彭斯之夜）。"},
{id:51,ch:3,d:3,src:["7.4","13.15"],y:1760,yl:"18th–19th century",en:"The Industrial Revolution (18th–19th century) transformed Britain from an agricultural to an industrial economy with rapid urbanisation. Manufacturing became the biggest source of employment in the 18th century.",yue:"Industrial Revolution（18–19 世紀）令英國由農業經濟轉為工業經濟，城市急速發展；18 世紀製造業成為最大就業來源。"},
{id:52,ch:3,d:3,src:["15.1"],y:1776,w:1,en:"In 1776, 13 British colonies in North America declared their independence (the American War of Independence).",yue:"1776 年北美 13 個英國殖民地宣布獨立（American War of Independence）。"},
{id:53,ch:3,d:4,src:["10.14"],y:1800,en:"The Act of Union 1800 united Great Britain and Ireland, creating the United Kingdom of Great Britain and Ireland.",yue:"Act of Union（聯合法案） 1800 合併 Great Britain 同 Ireland，成立 United Kingdom of Great Britain and Ireland（大不列顛及愛爾蘭聯合王國）。"},
{id:54,ch:3,d:3,src:["6.11","12.3","14.5"],y:1805,w:1,p:["Admiral Nelson","politician"],en:"At the Battle of Trafalgar (1805) Admiral Nelson commanded the British fleet, defeated the French and Spanish fleets, and was killed.",yue:"Battle of Trafalgar（1805 年）Admiral Nelson（納爾遜上將）指揮英國艦隊擊敗法國同西班牙艦隊，本人陣亡。"},
{id:55,ch:3,d:3,src:["8.15","14.23","16.18"],y:1807,p:["William Wilberforce","reformer"],en:"The Slave Trade Act 1807 abolished the slave trade in the British Empire; MP William Wilberforce led the campaign.",yue:"Slave Trade Act（奴隸貿易法案） 1807 廢除大英帝國嘅奴隸貿易，由國會議員 William Wilberforce（威廉·威伯福斯）推動。"},
{id:56,ch:3,d:4,src:["2.11","16.23"],y:1810,p:["Sake Dean Mahomet","reformer"],en:"Sake Dean Mahomet opened Britain's first curry house in London (around 1810) and introduced shampooing to Britain.",yue:"Sake Dean Mahomet（薩克·迪恩·馬霍梅特）約 1810 年喺倫敦開設英國第一間咖喱屋，並引入 shampooing（洗頭按摩）。"},
{id:57,ch:3,d:2,src:["4.0","4.23","9.1","16.12"],y:1815,w:1,p:["Duke of Wellington","politician"],en:"At the Battle of Waterloo (1815) the Duke of Wellington (\"the Iron Duke\") defeated Napoleon — the last battle between Britain and France. Wellington later became Prime Minister.",yue:"Battle of Waterloo（1815 年）Duke of Wellington（「Iron Duke（鐵公爵）」）打敗拿破崙，係英法之間最後一場戰役；Wellington（威靈頓）後來出任首相。"},
{id:58,ch:3,d:3,src:["7.23"],p:["Isambard Kingdom Brunel","scientist"],en:"Isambard Kingdom Brunel was a famous Victorian engineer who built bridges, tunnels, railways and ships.",yue:"Isambard Kingdom Brunel（布魯內爾）係維多利亞時代著名工程師，建造橋樑、隧道、鐵路同船隻。"},
{id:59,ch:3,d:4,src:["11.20","12.17"],y:1832,en:"The Great Reform Act 1832 extended the right to vote (to more of the middle classes).",yue:"Great Reform Act（大改革法案） 1832 擴大投票權（惠及中產階級）。"},
{id:60,ch:3,d:4,src:["5.14","10.13"],y:1838,yl:"1830s–1840s",en:"The Chartists (mid-19th century) campaigned for political reform, including votes for all men.",yue:"Chartists（19 世紀中）爭取政治改革，包括所有男性都有投票權。"},
{id:61,ch:3,d:3,src:["10.20","17.1"],y:1845,yl:"1840s",en:"The Irish famine (1840s) was caused by the failure of the potato crop; about a million people died and another million emigrated.",yue:"Irish famine（1840 年代）因薯仔失收造成，約 100 萬人死亡，另有約 100 萬人移民。"},
{id:62,ch:3,d:3,src:["5.7","10.18"],y:1854,w:1,p:["Florence Nightingale","reformer"],en:"Florence Nightingale, a pioneer of modern nursing, improved hospital conditions during the Crimean War (1853–1856).",yue:"Florence Nightingale（南丁格爾）係現代護理先驅，喺 Crimean War（1853–1856）期間改善醫院環境。"},
{id:63,ch:3,d:4,src:["6.10"],y:1899,w:1,en:"The Boer War (1899–1902) was fought in South Africa between the British and the Boer settlers.",yue:"Boer War（1899–1902）喺南非爆發，英國對抗布爾人（Boer）移民。"},
{id:64,ch:3,d:1,src:["5.8","6.19","7.9","13.23"],p:["Emmeline Pankhurst","reformer"],en:"The Suffragettes campaigned for women's right to vote; their leader was Emmeline Pankhurst.",yue:"Suffragettes（婦女參政運動者）爭取女性投票權，領袖係 Emmeline Pankhurst（艾米琳·潘克斯特）。"},
{id:65,ch:3,d:3,src:["15.23"],y:1914,w:1,en:"The First World War (1914–1918) was triggered by the assassination of Archduke Franz Ferdinand and a complex system of alliances.",yue:"第一次世界大戰（1914–1918）因 Archduke Franz Ferdinand（斐迪南大公）被刺殺同複雜嘅同盟關係而爆發。"},
{id:66,ch:3,d:4,src:["17.15"],y:1916,w:1,en:"The Battle of the Somme (1916) was one of the bloodiest battles of WWI: about 20,000 British soldiers died on the first day.",yue:"Battle of the Somme（1916 年）係一戰最血腥嘅戰役之一，第一日就有約 20,000 名英軍陣亡。"},
{id:67,ch:3,d:3,src:["4.12","15.5"],y:1918,w:1,en:"The First World War ended at 11am on 11th November 1918.",yue:"第一次世界大戰喺 1918 年 11 月 11 日上午 11 時結束。"},
{id:68,ch:3,d:4,src:["2.4","10.6"],y:1918,en:"In 1918 women over 30 were given the right to vote, in recognition of their contribution to the First World War.",yue:"1918 年 30 歲以上女性獲得投票權，以表揚佢哋喺一戰嘅貢獻。"},
{id:69,ch:3,d:4,src:["1.2","9.6"],y:1928,en:"In 1928 women were given the right to vote at 21, the same age as men.",yue:"1928 年女性投票年齡降至 21 歲，同男性一樣。"},
{id:70,ch:3,d:4,src:["7.21"],y:1969,en:"In 1969 the voting age was lowered to 18 for both men and women.",yue:"1969 年男女投票年齡一同降至 18 歲。"},
{id:71,ch:3,d:3,src:["9.10"],y:1928,p:["Alexander Fleming","scientist"],en:"Alexander Fleming, a Scottish scientist, discovered penicillin in 1928.",yue:"蘇格蘭科學家 Alexander Fleming（亞歷山大·弗萊明）喺 1928 年發現盤尼西林（penicillin）。"},
{id:72,ch:3,d:4,src:["1.20"],y:1930,yl:"1930s",p:["Sir Frank Whittle","scientist"],en:"Sir Frank Whittle invented the jet engine in the 1930s.",yue:"Sir Frank Whittle（法蘭克·惠特爾爵士）喺 1930 年代發明噴射引擎。"},
{id:73,ch:3,d:3,src:["6.22","8.0","15.22"],y:1939,w:1,en:"The Second World War began in 1939 when Germany invaded Poland; Britain and France declared war on Germany.",yue:"第二次世界大戰 1939 年因德國入侵波蘭而爆發，英法隨即向德國宣戰。"},
{id:74,ch:3,d:1,src:["2.8","14.12"],p:["Winston Churchill","politician"],en:"Winston Churchill was Prime Minister during WWII (1940–1945, and again 1951–1955), an inspirational leader known for his speeches.",yue:"Winston Churchill（邱吉爾）係二戰時期首相（1940–1945，1951–1955 再任），以鼓舞人心嘅演說聞名。"},
{id:75,ch:3,d:3,src:["3.18"],y:1940,w:1,en:"In 1940 British and Allied troops were evacuated from Dunkirk in France.",yue:"1940 年英軍同盟軍由法國 Dunkirk（敦克爾克）撤退。"},
{id:76,ch:3,d:3,src:["11.6","17.12"],y:1940,w:1,en:"The Battle of Britain (1940) was the crucial aerial battle in which Britain defended itself against German air attacks, preventing invasion.",yue:"Battle of Britain（1940 年）係關鍵空戰，英國成功抵禦德國空襲，阻止入侵。"},
{id:77,ch:3,d:3,src:["4.22"],y:1940,w:1,en:"During the Blitz (1940–1941) Germany bombed British cities, especially London.",yue:"Blitz（1940–1941）期間德國轟炸英國城市，尤其倫敦。"},
{id:78,ch:3,d:3,src:["2.23","16.6"],y:1945,w:1,en:"The Second World War ended in 1945: VE Day (Europe) on 8th May and VJ Day (Japan) on 15th August.",yue:"第二次世界大戰 1945 年結束：歐洲 5 月 8 日（歐洲勝利日 VE Day），日本 8 月 15 日（對日勝利日 VJ Day）。"},
{id:79,ch:3,d:4,src:["13.8"],y:1945,p:["Clement Attlee","politician"],en:"The Labour Party under Clement Attlee won the 1945 general election, despite Churchill's wartime popularity.",yue:"1945 年大選由 Clement Attlee（艾德禮）領導嘅工黨勝出，儘管 Churchill（邱吉爾）戰時聲望極高。"},
{id:80,ch:3,d:1,src:["9.9","12.10","13.14","17.7"],y:1948,p:["Aneurin Bevan","politician"],en:"The National Health Service (NHS) was founded in 1948 by the Labour government (Aneurin Bevan): healthcare free at the point of use for all UK residents.",yue:"國民保健服務（National Health Service, NHS）喺 1948 年由工黨政府（Aneurin Bevan 推動）成立，為所有英國居民提供免費醫療。"},
{id:81,ch:3,d:3,src:["11.14","17.20"],y:1946,yl:"post-1945",en:"After WWII the Labour government built the Welfare State: a system providing social security, healthcare and education.",yue:"二戰後工黨政府建立 Welfare State（福利國家），提供社會保障、醫療同教育。"},
{id:82,ch:3,d:3,src:["15.11"],y:1948,en:"The Windrush Generation were Caribbean immigrants who came to the UK after WWII, from 1948 onwards.",yue:"Windrush Generation（疾風世代）係二戰後（1948 年起）由加勒比海移居英國嘅移民。"},
{id:83,ch:3,d:4,src:["2.5"],y:1949,en:"Ireland became a republic in 1949.",yue:"愛爾蘭喺 1949 年成為共和國。"},
{id:84,ch:3,d:3,src:["8.6"],y:1953,p:["Francis Crick","scientist"],en:"Francis Crick (with James Watson) discovered the structure of DNA in 1953.",yue:"Francis Crick（弗朗西斯·克里克）同 James Watson（詹姆斯·華生）喺 1953 年發現 DNA 結構。"},
{id:85,ch:3,d:3,src:["5.20"],y:1953,p:["Edmund Hillary","sport"],en:"Edmund Hillary and Tenzing Norgay were the first to climb Mount Everest, in 1953, as part of a British expedition.",yue:"Edmund Hillary（艾德蒙·希拉里）同 Tenzing Norgay（丹增·諾蓋）喺 1953 年隨英國探險隊首次登上珠穆朗瑪峰。"},
{id:86,ch:3,d:3,src:["5.16"],y:1954,p:["Roger Bannister","sport"],en:"Roger Bannister was the first person to run a mile in under four minutes (1954).",yue:"Roger Bannister（羅傑·班尼斯特）喺 1954 年成為首位 4 分鐘內跑完 1 英里嘅人。"},
{id:87,ch:3,d:4,src:["2.7"],y:1960,yl:"1960s",p:["David Hockney","artist"],en:"David Hockney was an important contributor to the pop art movement of the 1960s.",yue:"David Hockney（大衛·霍克尼）係 1960 年代 pop art（普普藝術）運動嘅重要人物。"},
{id:88,ch:3,d:3,src:["1.10"],y:1966,p:["Bobby Moore","sport"],en:"Bobby Moore captained the England football team that won the World Cup in 1966.",yue:"Bobby Moore（波比·摩亞）係 1966 年奪得世界盃嘅英格蘭足球隊隊長。"},
{id:89,ch:3,d:3,src:["3.13"],y:1969,en:"Neil Armstrong was the first person to walk on the moon (1969, Apollo 11).",yue:"Neil Armstrong（岩士唐）喺 1969 年（Apollo 11）成為首位登月嘅人。"},
{id:90,ch:3,d:3,src:["3.9"],y:1969,en:"Concorde, the supersonic passenger aircraft, was developed by Britain and France.",yue:"Concorde（和諧式客機）超音速客機由英國同法國共同研發。"},
{id:91,ch:3,d:3,src:["3.17"],y:1973,en:"The UK joined the European Community (now the EU) in 1973, and left the EU in 2020.",yue:"英國 1973 年加入歐洲共同體（現歐盟），2020 年脫歐。"},
{id:92,ch:3,d:1,src:["1.8","11.7","17.4"],y:1979,p:["Margaret Thatcher","politician"],en:"Margaret Thatcher was the first female Prime Minister (1979–1990) and the longest-serving PM of the 20th century.",yue:"Margaret Thatcher（戴卓爾夫人）係首位女首相（1979–1990），亦係 20 世紀任期最長嘅首相。"},
{id:93,ch:3,d:4,src:["2.20"],y:1984,p:["Torvill & Dean","sport"],en:"Jayne Torvill and Christopher Dean won Olympic gold in ice dancing (1984).",yue:"Jayne Torvill（珍·托維爾）同 Christopher Dean（基斯杜化·迪恩）喺 1984 年奧運冰上舞蹈奪金。"},
{id:94,ch:3,d:3,src:["13.10"],y:1989,en:"The Berlin Wall fell in 1989, marking the end of the Cold War.",yue:"柏林圍牆 1989 年倒下，象徵冷戰結束。"},
{id:95,ch:3,d:3,src:["14.7"],y:1989,p:["Tim Berners-Lee","scientist"],en:"Tim Berners-Lee, a British computer scientist, invented the World Wide Web (1989).",yue:"英國電腦科學家 Tim Berners-Lee（添·柏納斯-李）喺 1989 年發明 World Wide Web（萬維網）。"},
{id:96,ch:3,d:3,src:["13.21","15.13","16.19"],y:1998,en:"The Good Friday Agreement (1998) brought peace to Northern Ireland after decades of conflict.",yue:"Good Friday Agreement（1998 年）為北愛爾蘭帶來和平，結束數十年衝突。"},
{id:97,ch:3,d:2,src:["6.9"],p:["Alexander Graham Bell","scientist"],en:"Alexander Graham Bell, born in Scotland, invented the telephone.",yue:"蘇格蘭出生嘅 Alexander Graham Bell（亞歷山大·貝爾）發明電話。"},
{id:98,ch:4,d:2,src:["10.0","7.15","13.0"],en:"St George is the patron saint of England; St George's Day is 23rd April.",yue:"St George 係英格蘭守護聖人，St George's Day（聖佐治日）係 4 月 23 日。"},
{id:99,ch:4,d:3,src:["1.4","5.21"],en:"St Andrew is the patron saint of Scotland; St Andrew's Day is 30th November.",yue:"St Andrew 係蘇格蘭守護聖人，St Andrew's Day（聖安德魯日）係 11 月 30 日。"},
{id:100,ch:4,d:4,src:["5.13"],en:"St Andrew was crucified on an X-shaped cross; the Scottish flag (the Saltire) is a white X-shaped cross on blue.",yue:"St Andrew（聖安德魯）被釘死喺 X 形十字架上，所以蘇格蘭國旗（Saltire）係藍底白色 X 形十字。"},
{id:101,ch:4,d:3,src:["2.15","8.4"],en:"St David is the patron saint of Wales; St David's Day is 1st March.",yue:"St David 係威爾斯守護聖人，St David's Day（聖大衛日）係 3 月 1 日。"},
{id:102,ch:4,d:2,src:["11.9","8.22","14.0"],en:"St Patrick is the patron saint of Northern Ireland; St Patrick's Day is 17th March.",yue:"St Patrick 係北愛爾蘭守護聖人，St Patrick's Day（聖柏德烈日）係 3 月 17 日。"},
{id:103,ch:4,d:2,src:["4.15","11.15"],en:"The Church of England is the established Protestant church of England, founded by Henry VIII. The Monarch is its head; the Archbishop of Canterbury is its spiritual leader.",yue:"Church of England（英格蘭國教會）係英格蘭嘅國教（新教），由 Henry VIII（亨利八世）創立。君主係其元首，Archbishop of Canterbury（坎特伯雷大主教）係精神領袖。"},
{id:104,ch:4,d:3,src:["3.15","5.6"],en:"The Church of Scotland is a Presbyterian church.",yue:"Church of Scotland（蘇格蘭教會）係長老會（Presbyterian）教會。"},
{id:105,ch:4,d:5,src:["3.1","6.4","10.2"],en:"Wales and Northern Ireland do NOT have an established church; only England and Scotland do.",yue:"威爾斯同北愛爾蘭冇國教，只有英格蘭同蘇格蘭有。"},
{id:106,ch:4,d:2,src:["5.0","1.23"],en:"Easter takes place in March or April. Lent is the 40 days before Easter.",yue:"Easter（復活節）喺 3 月或 4 月；Lent（大齋期）係 Easter 前嘅 40 日。"},
{id:107,ch:4,d:1,src:["10.4"],en:"Boxing Day is 26th December, the day after Christmas Day, and is a public holiday.",yue:"Boxing Day（節禮日）係 12 月 26 日（聖誕翌日），係公眾假期。"},
{id:108,ch:4,d:2,src:["3.10"],en:"Eid al-Fitr is a Muslim festival marking the end of Ramadan.",yue:"Eid al-Fitr（開齋節）係伊斯蘭節日，慶祝齋戒月（Ramadan）結束。"},
{id:109,ch:4,d:3,src:["5.15"],en:"Eid ul Adha is an Islamic festival remembering Ibrahim's willingness to sacrifice his son.",yue:"Eid ul Adha（宰牲節）係伊斯蘭節日，紀念 Ibrahim（易卜拉欣）願意犧牲兒子。"},
{id:110,ch:4,d:2,src:["4.11","11.3","15.17"],en:"Diwali, the Festival of Lights, is celebrated by Hindus and Sikhs.",yue:"Diwali（光明節）由印度教徒同錫克教徒慶祝。"},
{id:111,ch:4,d:3,src:["5.18"],en:"Vaisakhi is a Sikh festival (April) marking the founding of the Khalsa.",yue:"Vaisakhi（光輝節）係錫克教節日（4 月），紀念 Khalsa（卡爾沙）成立。"},
{id:112,ch:4,d:1,src:["6.16","7.1"],en:"Halloween is on 31st October.",yue:"Halloween（萬聖節）係 10 月 31 日。"},
{id:113,ch:4,d:2,src:["3.23","14.20"],en:"Bonfire Night (Guy Fawkes Night) on 5th November commemorates the failure of the Gunpowder Plot of 1605.",yue:"Bonfire Night（Guy Fawkes Night（蓋伊·福克斯之夜））11 月 5 日，紀念 1605 年 Gunpowder Plot（火藥陰謀）失敗。"},
{id:114,ch:4,d:1,src:["3.2","9.7","11.22","12.19"],en:"Hogmanay is the Scottish name for New Year's Eve (31st December).",yue:"Hogmanay（霍格莫尼）係蘇格蘭對除夕（12 月 31 日）嘅稱呼。"},
{id:115,ch:4,d:1,src:["2.17","9.11","14.13","17.22"],en:"Remembrance Day (Armistice Day), 11th November, commemorates the end of WWI at 11am in 1918 and those who died in wars; people wear red poppies.",yue:"Remembrance Day（Armistice Day（停戰紀念日））11 月 11 日，紀念 1918 年一戰結束同戰爭死難者，人們佩戴紅色罌粟花。"},
{id:116,ch:4,d:1,src:["1.7","11.8"],geo:["England","landmark"],en:"The Cenotaph is a war memorial in Whitehall, London, where the Remembrance Day ceremony is held.",yue:"Cenotaph（戰爭紀念碑）係倫敦 Whitehall（白廳）嘅戰爭紀念碑，Remembrance Day（國殤紀念日）儀式喺呢度舉行。"},
{id:117,ch:4,d:1,src:["1.15","10.5","13.4"],en:"Public holidays in the UK are called bank holidays: days when banks and many businesses are closed.",yue:"英國公眾假期叫 bank holidays（銀行假期），當日銀行同好多商戶休息。"},
{id:118,ch:4,d:2,src:["8.12"],en:"The national flower of England is the (Tudor) rose.",yue:"英格蘭國花係玫瑰（Tudor rose）。"},
{id:119,ch:4,d:2,src:["8.1"],en:"The national flower of Scotland is the thistle.",yue:"蘇格蘭國花係薊花（thistle）。"},
{id:120,ch:4,d:2,src:["4.1"],en:"The national flower of Wales is the daffodil.",yue:"威爾斯國花係水仙花（daffodil）。"},
{id:121,ch:4,d:2,src:["9.0","9.19"],en:"The national flower of Northern Ireland is the shamrock.",yue:"北愛爾蘭國花係三葉草（shamrock）。"},
{id:122,ch:4,d:2,src:["14.6"],en:"The Union Jack is red, white and blue, combining the crosses of England, Scotland and Ireland.",yue:"Union Jack（英國國旗）係紅、白、藍三色，結合英格蘭、蘇格蘭同愛爾蘭嘅十字。"},
{id:123,ch:4,d:1,src:["6.20"],geo:["Wales","region"],en:"Welsh is spoken in Wales alongside English.",yue:"威爾斯除英文外亦講威爾斯語（Welsh）。"},
{id:124,ch:4,d:3,src:["13.12"],en:"Gaelic is a Celtic language spoken in parts of Scotland and Ireland.",yue:"Gaelic（蓋爾語）係凱爾特語言，喺蘇格蘭同愛爾蘭部分地區使用。"},
{id:125,ch:4,d:4,src:["11.2","5.1"],en:"The UK currency is the pound sterling (£). Coins: 1p, 2p, 5p, 10p, 20p, 50p, £1 and £2 (there is no 25p coin).",yue:"英國貨幣係英鎊（pound sterling, £）。硬幣有 1p、2p、5p、10p、20p、50p、£1、£2，冇 25p。"},
{id:126,ch:4,d:5,src:["3.22","9.2","4.4"],en:"The highest-value note in England is £50 (Scottish banks issue £100). Scotland and Northern Ireland have their own banknotes, which are valid everywhere in the UK.",yue:"英格蘭最高面值紙幣係 £50（蘇格蘭銀行有 £100）。蘇格蘭同北愛爾蘭有自己嘅紙幣，全英國通用。"},
{id:127,ch:4,d:1,src:["4.10"],geo:["England","city"],en:"The capital city of England (and the UK) is London.",yue:"英格蘭（同英國）首都係 London（倫敦）。"},
{id:128,ch:4,d:1,src:["2.16","9.23"],geo:["Scotland","city"],en:"The capital city of Scotland is Edinburgh.",yue:"蘇格蘭首都係 Edinburgh（愛丁堡）。"},
{id:129,ch:4,d:1,src:["2.21"],geo:["Wales","city"],en:"The capital city of Wales is Cardiff.",yue:"威爾斯首都係 Cardiff（加的夫）。"},
{id:130,ch:4,d:1,src:["3.16","9.8"],geo:["Northern Ireland","city"],en:"The capital city of Northern Ireland is Belfast.",yue:"北愛爾蘭首都係 Belfast（貝爾法斯特）。"},
{id:131,ch:4,d:1,src:["1.1"],geo:["England","landmark"],en:"Big Ben is the clock tower bell at the Houses of Parliament in London.",yue:"Big Ben（大笨鐘）係倫敦國會大廈（Houses of Parliament）鐘樓嘅大鐘。"},
{id:132,ch:4,d:1,src:["10.11"],geo:["England","landmark"],en:"Buckingham Palace is the Monarch's official residence in London.",yue:"Buckingham Palace（白金漢宮）係君主喺倫敦嘅官邸。"},
{id:133,ch:4,d:2,src:["3.8","12.11","10.17"],geo:["England","landmark"],en:"The Tower of London is guarded by the Yeoman Warders, known as Beefeaters, who also give tours. The Crown Jewels (royal regalia used at coronations) are kept there.",yue:"Tower of London（倫敦塔）由 Yeoman Warders（俗稱 Beefeaters）守衛及導賞；加冕用嘅 Crown Jewels（王室珠寶）亦存放喺度。"},
{id:134,ch:4,d:1,src:["11.19"],geo:["Scotland","landmark"],en:"Edinburgh Castle is in Edinburgh, Scotland.",yue:"Edinburgh Castle（愛丁堡城堡）喺蘇格蘭 Edinburgh。"},
{id:135,ch:4,d:2,src:["7.18","16.1"],geo:["Northern Ireland","nature"],en:"The Giant's Causeway is in Northern Ireland: basalt columns formed by volcanic lava about 50 million years ago.",yue:"Giant's Causeway（巨人堤道）喺北愛爾蘭，係約 5,000 萬年前火山熔岩形成嘅玄武岩柱。"},
{id:136,ch:4,d:3,src:["4.18","5.2"],geo:["England","landmark"],en:"The Eden Project is a visitor attraction in Cornwall (south-west England) with giant greenhouse biomes.",yue:"Eden Project（伊甸園計劃）喺英格蘭西南部 Cornwall（康沃爾），係有巨型溫室生態館嘅景點。"},
{id:137,ch:4,d:2,src:["3.12","4.14","7.10"],geo:["Wales","nature"],en:"Snowdonia National Park is in Wales; Snowdon is the highest mountain in Wales.",yue:"Snowdonia National Park（斯諾登尼亞國家公園）喺威爾斯；Snowdon 係威爾斯最高山。"},
{id:138,ch:4,d:2,src:["4.8"],geo:["Scotland","nature"],en:"Ben Nevis, in Scotland, is the highest mountain in the UK (1,345 m).",yue:"Ben Nevis（本尼維斯山）喺蘇格蘭，係英國最高山（1,345 米）。"},
{id:139,ch:4,d:3,src:["9.3","13.1"],geo:["England","nature"],en:"The Lake District is the largest National Park in England.",yue:"Lake District（湖區）係英格蘭最大嘅國家公園。"},
{id:140,ch:4,d:3,src:["10.1"],geo:["Scotland","nature"],en:"Loch Lomond and the Trossachs National Park is in Scotland.",yue:"Loch Lomond and the Trossachs National Park（羅蒙湖與特羅薩克斯國家公園）喺蘇格蘭。"},
{id:141,ch:4,d:3,src:["6.3"],geo:["UK","nature"],en:"National Parks are areas of protected countryside; there are 15 in England, Wales and Scotland.",yue:"National Parks（國家公園）係受保護嘅鄉郊地區，英格蘭、威爾斯同蘇格蘭共有 15 個。"},
{id:142,ch:4,d:2,src:["7.3"],en:"The Ashes is the famous cricket series played between England and Australia.",yue:"The Ashes（灰燼盃）係英格蘭同澳洲之間著名嘅板球系列賽。"},
{id:143,ch:4,d:1,src:["10.16","12.21"],en:"Wimbledon is an annual Grand Slam lawn tennis tournament held in London.",yue:"Wimbledon（溫布頓）係每年喺倫敦舉行嘅草地網球大滿貫賽事。"},
{id:144,ch:4,d:2,src:["6.7"],en:"The Commonwealth Games is a multi-sport event held every four years for Commonwealth countries.",yue:"Commonwealth Games（英聯邦運動會）係每 4 年舉行一次、英聯邦國家參加嘅綜合運動會。"},
{id:145,ch:4,d:3,src:["6.13","8.10"],en:"The BBC Proms is an annual eight-week classical music festival held at the Royal Albert Hall in London.",yue:"英國廣播公司（BBC）逍遙音樂節（BBC Proms）係每年為期 8 週嘅古典音樂節，喺倫敦 Royal Albert Hall（皇家阿爾伯特音樂廳）舉行。"},
{id:146,ch:4,d:2,src:["5.10","8.16"],en:"The Notting Hill Carnival is a Caribbean-influenced street festival held in London every August.",yue:"Notting Hill Carnival（諾丁山嘉年華）係每年 8 月喺倫敦舉行、充滿加勒比海色彩嘅街頭嘉年華。"},
{id:147,ch:4,d:3,src:["11.21","13.19"],en:"Glastonbury is a famous annual music festival held in Somerset, England.",yue:"Glastonbury（格拉斯頓伯里音樂節）係每年喺英格蘭 Somerset（薩默塞特）舉行嘅著名音樂節。"},
{id:148,ch:4,d:3,src:["11.1"],geo:["England","landmark"],en:"London's West End is known as Theatreland.",yue:"倫敦 West End（西區）被稱為 Theatreland（劇院區）。"},
{id:149,ch:4,d:2,src:["12.6"],geo:["England","landmark"],en:"The Tate galleries (Tate Britain and Tate Modern) are in London.",yue:"Tate（泰特）美術館（Tate Britain 同 Tate Modern）喺倫敦。"},
{id:150,ch:4,d:3,src:["8.7"],geo:["Scotland","landmark"],en:"The National Galleries of Scotland are in Edinburgh.",yue:"National Galleries of Scotland（蘇格蘭國家美術館）喺 Edinburgh（愛丁堡）。"},
{id:151,ch:4,d:3,src:["7.22"],en:"The Turner Prize is an annual prize awarded to British visual artists.",yue:"Turner Prize（透納獎）係每年頒發俾英國視覺藝術家嘅獎項。"},
{id:152,ch:4,d:4,src:["10.15"],p:["J.M.W. Turner","artist"],en:"J.M.W. Turner, a famous British landscape painter, painted 'The Fighting Temeraire'.",yue:"英國著名風景畫家 J.M.W. Turner（透納）畫咗 The Fighting Temeraire（戰鬥的泰梅萊爾號）。"},
{id:153,ch:4,d:4,src:["10.9"],p:["Purcell & Handel","artist"],en:"Henry Purcell and George Frideric Handel were two famous Baroque composers associated with Britain.",yue:"Henry Purcell（普賽爾）同 George Frideric Handel（韓德爾）係同英國有關嘅兩位著名巴洛克作曲家。"},
{id:154,ch:4,d:4,src:["5.9"],p:["Richard Rogers","artist"],en:"Richard Rogers was the architect of the Millennium Dome.",yue:"Richard Rogers（理查德·羅傑斯）係 Millennium Dome（千禧巨蛋）嘅建築師。"},
{id:155,ch:4,d:2,src:["15.3","16.4"],en:"Harry Potter and James Bond are two of the highest-grossing film franchises produced in the UK.",yue:"Harry Potter（哈利波特）同 James Bond（占士邦）係英國製作、最高票房嘅電影系列。"},
{id:156,ch:4,d:5,src:["14.3"],en:"British actors who have won Oscars include Colin Firth, Anthony Hopkins, Judi Dench, Kate Winslet and Tilda Swinton (Emily Watson has not).",yue:"曾獲奧斯卡嘅英國演員包括 Colin Firth（哥連·費夫）、Anthony Hopkins（安東尼·鶴健士）、Judi Dench（茱迪·丹芝）、Kate Winslet（琦·溫絲莉）、Tilda Swinton（Emily Watson（艾美莉·屈臣）未獲獎）。"},
{id:157,ch:4,d:2,src:["10.21","12.1"],en:"The BBC is the largest broadcaster in the world and is independent of government.",yue:"英國廣播公司（BBC）係全球最大廣播機構，獨立於政府。"},
{id:158,ch:4,d:4,src:["15.20"],y:1994,en:"The National Lottery (launched 1994) raises money for good causes including arts, sport and heritage.",yue:"National Lottery（1994 年推出）為藝術、體育同文化遺產等公益事業籌款。"},
{id:159,ch:4,d:1,src:["3.19","8.18"],p:["Charles Dickens","writer"],en:"Charles Dickens was a famous Victorian novelist who wrote 'A Christmas Carol' (also Oliver Twist, Great Expectations).",yue:"Charles Dickens（狄更斯）係維多利亞時代著名小說家，作品有 A Christmas Carol（聖誕頌歌）、Oliver Twist（孤雛淚）等。"},
{id:160,ch:4,d:2,src:["4.21"],p:["Jane Austen","writer"],en:"Jane Austen wrote 'Pride and Prejudice'.",yue:"Jane Austen（珍·奧斯汀）寫咗 Pride and Prejudice（傲慢與偏見）。"},
{id:161,ch:4,d:2,src:["15.10"],p:["Charlotte Brontë","writer"],en:"Charlotte Brontë wrote 'Jane Eyre'.",yue:"Charlotte Brontë（夏綠蒂·勃朗特）寫咗 Jane Eyre（簡愛）。"},
{id:162,ch:4,d:2,src:["16.14"],p:["Mary Shelley","writer"],en:"Mary Shelley wrote 'Frankenstein'.",yue:"Mary Shelley（瑪麗·雪萊）寫咗 Frankenstein（科學怪人）。"},
{id:163,ch:4,d:3,src:["1.21"],p:["William Wordsworth","writer"],en:"William Wordsworth wrote the poem 'The Daffodils'.",yue:"William Wordsworth（華茲華斯）寫咗詩作 The Daffodils（水仙花）。"},
{id:164,ch:4,d:3,src:["12.22"],p:["John Keats","writer"],en:"John Keats wrote the poem 'Ode to a Nightingale'.",yue:"John Keats（濟慈）寫咗詩作 Ode to a Nightingale（夜鶯頌）。"},
{id:165,ch:4,d:3,src:["11.12","14.21"],p:["Rudyard Kipling","writer"],en:"Rudyard Kipling wrote the poem 'If' and 'The Jungle Book'.",yue:"Rudyard Kipling（吉卜林）寫咗詩作 If 同小說 The Jungle Book（森林王子）。"},
{id:166,ch:5,d:2,src:["13.9","14.16","16.21"],en:"The Monarch is the ceremonial head of state, signs legislation but acts on the advice of the Prime Minister, and must remain politically neutral.",yue:"君主係禮儀性國家元首，簽署法例但按首相建議行事，必須保持政治中立。"},
{id:167,ch:5,d:2,src:["2.12","10.12"],en:"The Monarch appoints the Prime Minister: by convention, the leader of the party with the most seats in the House of Commons.",yue:"君主任命首相，慣例上係下議院議席最多政黨嘅領袖。"},
{id:168,ch:5,d:3,src:["13.18","17.10"],en:"At the State Opening of Parliament the Monarch opens the new session and reads the King's/Queen's Speech, which sets out the government's legislative programme (written by the PM).",yue:"國會開幕大典上君主宣布新會期開始並宣讀 King's/Queen's Speech（國王/女王演說），內容係政府立法計劃（由首相撰寫）。"},
{id:169,ch:5,d:5,src:["17.0"],en:"The UK's constitutional institutions are the Monarchy, Parliament, the Prime Minister, the Cabinet, the judiciary, the police, the civil service and local government. The Armed Forces are NOT one.",yue:"英國憲制機構包括君主、國會、首相、內閣、司法機構、警察、公務員同地方政府；軍隊唔係。"},
{id:170,ch:5,d:1,src:["5.17"],en:"Parliament has two houses: the House of Commons and the House of Lords.",yue:"國會有兩院：House of Commons（下議院）同 House of Lords（上議院）。"},
{id:171,ch:5,d:2,src:["3.11","6.15"],en:"The UK has 650 parliamentary constituencies, each electing one MP — so there are 650 MPs in the House of Commons.",yue:"英國有 650 個選區，每區選出一名國會議員（Member of Parliament, MP），所以下議院有 650 名議員。"},
{id:172,ch:5,d:2,src:["1.9"],en:"The Speaker chairs debates in the House of Commons.",yue:"Speaker（議長）主持下議院辯論。"},
{id:173,ch:5,d:1,src:["4.19","7.16","17.23"],en:"The House of Lords examines, revises and debates laws proposed by the House of Commons (it cannot reject financial bills).",yue:"上議院審議、修訂同辯論下議院提出嘅法案（不能否決財政法案）。"},
{id:174,ch:5,d:2,src:["7.20"],en:"Life peers are members of the House of Lords appointed for their lifetime only; the title cannot be inherited. Most members of the Lords are now life peers.",yue:"Life peers（終身貴族）係終身制上議院議員，頭銜唔可以世襲；現時大部分上議院議員係 life peers（終身貴族）。"},
{id:175,ch:5,d:4,src:["16.13"],en:"Hereditary peers inherit their title; only 92 remain in the House of Lords.",yue:"Hereditary peers（世襲貴族）係世襲貴族，上議院只剩 92 位。"},
{id:176,ch:5,d:5,src:["2.2"],en:"Several Church of England bishops (the Lords Spiritual, 26 in total) sit in the House of Lords.",yue:"多位 Church of England（英格蘭國教會）主教（Lords Spiritual，共 26 位）係上議院成員。"},
{id:177,ch:5,d:1,src:["5.12","6.21","15.9","17.3"],en:"An MP is elected by the voters of a constituency and represents everyone in it, helps to create new laws, and scrutinises the government.",yue:"國會議員（Member of Parliament, MP）由選區選民選出，代表選區內所有人、協助制定法律、監察政府。"},
{id:178,ch:5,d:2,src:["7.13"],en:"A by-election is held when an MP dies or resigns.",yue:"補選（by-election）喺國會議員（Member of Parliament, MP）去世或辭職時舉行。"},
{id:179,ch:5,d:3,src:["12.13"],en:"Prime Minister's Questions (PMQs) is a weekly session (usually Wednesday) where MPs question the Prime Minister.",yue:"首相答問（Prime Minister's Questions, PMQs）係每週一次（通常星期三）國會議員質詢首相嘅環節。"},
{id:180,ch:5,d:3,src:["14.11"],en:"A hung parliament is when no single party wins enough seats for a majority.",yue:"Hung parliament（懸浮議會）係冇單一政黨取得過半議席嘅情況。"},
{id:181,ch:5,d:1,src:["16.8","4.9"],geo:["England","landmark"],en:"The Prime Minister is head of government, leads the Cabinet and advises the Monarch. The official home of the PM is 10 Downing Street.",yue:"首相係政府首長，領導內閣並向君主提供建議；官邸係 10 Downing Street（唐寧街）。"},
{id:182,ch:5,d:2,src:["5.11"],en:"The Cabinet, chaired by the PM and made up of about 20 senior ministers, makes major government policy decisions.",yue:"內閣由首相主持、約 20 位資深部長組成，負責重大政策決定。"},
{id:183,ch:5,d:2,src:["9.12","17.2"],en:"The Shadow Cabinet is made up of senior opposition MPs, appointed by the Leader of the Opposition, who mirror Cabinet ministers and challenge the government.",yue:"Shadow Cabinet（影子內閣）由反對黨領袖委任嘅資深反對黨議員組成，對應各內閣部長並挑戰政府。"},
{id:184,ch:5,d:2,src:["2.0","8.3"],en:"The Home Secretary is responsible for crime, policing and immigration.",yue:"Home Secretary（內政大臣）負責犯罪、警政同移民。"},
{id:185,ch:5,d:2,src:["7.11","12.15"],en:"The Chancellor of the Exchequer is responsible for the country's finances and the economy.",yue:"Chancellor of the Exchequer（財政大臣）負責國家財政同經濟。"},
{id:186,ch:5,d:4,src:["8.20"],en:"The Lord Chancellor is responsible for the legal system and courts in England and Wales.",yue:"Lord Chancellor（大法官）負責英格蘭同威爾斯嘅法律制度同法院。"},
{id:187,ch:5,d:4,src:["9.22"],en:"The Attorney General is the chief legal adviser to the government.",yue:"Attorney General（總檢察長）係政府首席法律顧問。"},
{id:188,ch:5,d:3,src:["11.17"],en:"The Civil Service implements government policy and must remain politically neutral.",yue:"Civil Service（公務員）執行政府政策，必須保持政治中立。"},
{id:189,ch:5,d:3,src:["16.11"],en:"The Ombudsman investigates complaints about government departments and public services.",yue:"Ombudsman（申訴專員）調查對政府部門同公共服務嘅投訴。"},
{id:190,ch:5,d:2,src:["4.3"],en:"General elections are held at least every 5 years.",yue:"大選至少每 5 年舉行一次。"},
{id:191,ch:5,d:2,src:["8.8","17.18"],en:"UK general elections use the 'first past the post' system: the candidate with the most votes in a constituency wins.",yue:"英國大選採用 first past the post（領先者當選制）制度：選區內得票最多嘅候選人勝出。"},
{id:192,ch:5,d:4,src:["17.6","14.1"],en:"Proportional representation gives seats in proportion to votes received; it is used for the Northern Ireland Assembly (and the Scottish Parliament and Senedd).",yue:"比例代表制（proportional representation）按得票比例分配議席，北愛爾蘭議會（以及蘇格蘭議會同 Senedd）採用此制度。"},
{id:193,ch:5,d:2,src:["8.17"],en:"A referendum is a public vote on a specific issue (e.g. the 2016 EU referendum).",yue:"公投（referendum）係就特定議題進行嘅全民投票（例如 2016 年脫歐公投）。"},
{id:194,ch:5,d:3,src:["13.13"],en:"To vote in a general election you must be 18 or over, a UK, Irish or Commonwealth citizen, and on the electoral register.",yue:"大選投票資格：年滿 18 歲、英國/愛爾蘭/英聯邦公民、已登記選民冊。"},
{id:195,ch:5,d:3,src:["1.16"],en:"Before an election you are sent a poll card telling you where and when to vote; you use a ballot paper to vote.",yue:"選舉前會收到 poll card（投票通知卡），列明投票地點同時間；投票時用 ballot paper（選票）。"},
{id:196,ch:5,d:4,src:["1.18"],en:"By law, television and radio must give balanced political coverage before an election; newspapers are not bound by this rule.",yue:"法律規定電視同電台喺選舉前必須平衡報道政治新聞，報章不受此限。"},
{id:197,ch:5,d:3,src:["17.11"],en:"The Electoral Commission oversees elections and maintains the electoral register.",yue:"Electoral Commission（選舉委員會）監督選舉並管理選民登記冊。"},
{id:198,ch:5,d:2,src:["10.10"],en:"Devolution is the transfer of power from central government to regional governments — Scotland, Wales and Northern Ireland each have their own parliament or assembly.",yue:"Devolution（權力下放）係中央政府將權力轉移俾地區政府；蘇格蘭、威爾斯同北愛爾蘭各有自己嘅議會。"},
{id:199,ch:5,d:4,src:["6.8","8.19","13.7"],geo:["Scotland","city"],en:"The Scottish Parliament, in Edinburgh, has 129 members (MSPs).",yue:"蘇格蘭議會（Scottish Parliament）位於 Edinburgh（愛丁堡），有 129 名議員（MSP, Member of the Scottish Parliament）。"},
{id:200,ch:5,d:4,src:["4.20","5.22","7.17"],geo:["Wales","city"],en:"The Welsh Parliament (Senedd Cymru, formerly the National Assembly for Wales), in Cardiff, has 60 members (MSs).",yue:"威爾斯議會（Senedd Cymru，前稱 National Assembly for Wales）位於 Cardiff（加的夫），有 60 名議員（MS, Member of the Senedd）。"},
{id:201,ch:5,d:4,src:["9.18","12.2"],geo:["Northern Ireland","city"],en:"The Northern Ireland Assembly has 90 members (MLAs).",yue:"北愛爾蘭議會（Northern Ireland Assembly）有 90 名議員（MLA, Member of the Legislative Assembly）。"},
{id:202,ch:5,d:5,src:["12.12"],en:"Defence, foreign affairs and immigration are NOT devolved — they are reserved to the UK government.",yue:"國防、外交同移民唔係下放事務，保留俾英國中央政府。"},
{id:203,ch:5,d:3,src:["9.14","12.18","12.5"],en:"Towns, cities and rural areas are governed by democratically elected local councils, which provide services such as education, waste and housing. Councillors represent their community and decide on local services.",yue:"城鎮同鄉郊由民選地方議會管理，提供教育、廢物處理、房屋等服務；議員代表社區並決定地方服務。"},
{id:204,ch:5,d:2,src:["2.22","5.23","11.10"],en:"Habeas corpus is the legal principle that prevents people from being held in prison without trial.",yue:"Habeas corpus（人身保護令）係防止未經審訊而被囚禁嘅法律原則。"},
{id:205,ch:5,d:3,src:["15.8"],en:"Common law is law based on court decisions and precedents rather than legislation.",yue:"Common law（普通法）係基於法院判決同先例而非成文法例嘅法律。"},
{id:206,ch:5,d:2,src:["14.19"],en:"Presumption of innocence: a person is considered innocent until proven guilty.",yue:"無罪推定（presumption of innocence）：未被證明有罪之前視為無罪。"},
{id:207,ch:5,d:2,src:["14.8"],en:"Trial by jury: a panel of citizens decides whether the accused is guilty or innocent.",yue:"陪審團審訊（trial by jury）：由一組公民裁定被告有罪與否。"},
{id:208,ch:5,d:3,src:["1.13","1.14","5.5"],en:"Jurors are aged 18 to 70 and are chosen randomly from the electoral register.",yue:"陪審員年齡 18 至 70 歲，由選民登記冊隨機抽選。"},
{id:209,ch:5,d:2,src:["7.6"],en:"Carrying an offensive weapon is a criminal offence.",yue:"攜帶攻擊性武器係刑事罪行。"},
{id:210,ch:5,d:3,src:["3.14"],en:"The small claims court deals with minor civil disputes.",yue:"小額錢債法庭（small claims court）處理小型民事糾紛。"},
{id:211,ch:5,d:3,src:["6.17"],y:2009,en:"The Supreme Court (established 2009) is the highest court in the UK.",yue:"Supreme Court（2009 年成立）係英國最高法院。"},
{id:212,ch:5,d:4,src:["16.5"],en:"Youth Courts in England and Wales (for those aged 10–17) are heard by specially trained magistrates or district judges; serious cases go to the Crown Court.",yue:"英格蘭同威爾斯嘅少年法庭（10–17 歲）由受過特別訓練嘅裁判官或地區法官審理，嚴重案件轉介 Crown Court（刑事法院）。"},
{id:213,ch:5,d:3,src:["1.17","14.22"],en:"Solicitors give legal advice and represent clients; their charges are usually based on how much time they spend on a case.",yue:"律師（solicitor）提供法律意見並代表客戶，收費通常按處理案件所花時間計算。"},
{id:214,ch:5,d:2,src:["14.17"],en:"Legal aid helps people who cannot afford to pay for legal advice.",yue:"法律援助（legal aid）幫助負擔唔起法律意見費用嘅人。"},
{id:215,ch:5,d:2,src:["17.16"],en:"Citizens Advice gives free, confidential advice on rights, legal matters and other issues.",yue:"Citizens Advice（公民諮詢局）提供免費、保密嘅權益、法律等諮詢服務。"},
{id:216,ch:5,d:2,src:["6.14"],en:"The role of the police is to protect life and property, and to prevent and detect crime.",yue:"警察職責係保護生命同財產、預防同偵查罪案。"},
{id:217,ch:5,d:4,src:["1.12","8.2"],en:"You can complain about the police by writing to the Chief Constable, at a police station, or to the independent complaints body (IOPC).",yue:"投訴警察可以寫信俾警察總長（Chief Constable）、親身去警署，或向獨立警察投訴機構（Independent Office for Police Conduct, IOPC）投訴。"},
{id:218,ch:5,d:2,src:["3.6"],en:"If you think someone is trying to persuade you to join an extremist or terrorist cause, contact your local police force.",yue:"如懷疑有人游說你加入極端或恐怖組織，應聯絡當地警方。"},
{id:219,ch:5,d:2,src:["13.16"],en:"Trade unions represent workers' interests and negotiate with employers.",yue:"工會代表工人利益，同僱主談判。"},
{id:220,ch:5,d:4,src:["14.14"],y:1998,en:"The National Minimum Wage (introduced 1998) is the minimum hourly wage employers must pay.",yue:"National Minimum Wage（1998 年推行）係僱主必須支付嘅最低時薪。"},
{id:221,ch:5,d:3,src:["14.10"],y:1998,en:"The Human Rights Act 1998 incorporated the European Convention on Human Rights into UK law.",yue:"Human Rights Act（人權法） 1998 將歐洲人權公約納入英國法律。"},
{id:222,ch:5,d:3,src:["15.14","16.7"],y:2010,en:"The Equality Act 2010 protects people from discrimination based on protected characteristics such as age, sex, race and religion.",yue:"Equality Act（平等法） 2010 保障人們免受基於年齡、性別、種族、宗教等受保護特徵嘅歧視。"},
{id:223,ch:5,d:3,src:["12.20"],en:"The Equality and Human Rights Commission protects and promotes equality and human rights in Britain.",yue:"Equality and Human Rights Commission（平等及人權委員會）負責保障同推廣英國嘅平等同人權。"},
{id:224,ch:5,d:4,src:["2.3"],en:"When walking your dog in a public place, it must wear a collar showing the name and address of the owner.",yue:"喺公眾地方遛狗，狗隻必須戴上寫有主人姓名同地址嘅頸圈。"},
{id:225,ch:5,d:4,src:["3.7","15.15"],en:"The National Citizen Service is a voluntary (not compulsory) programme for 16–17 year olds to develop skills and serve their community.",yue:"National Citizen Service（國民公民服務）係俾 16–17 歲青年參加嘅自願（非強制）計劃，培養技能同服務社區。"},
{id:226,ch:5,d:2,src:["4.5"],en:"The National Trust is a charity that preserves important buildings, coastline and countryside in the UK.",yue:"National Trust（國民信託）係保育重要建築、海岸線同鄉郊嘅慈善機構。"},
{id:227,ch:5,d:3,src:["11.5"],en:"Friends of the Earth is a charity that helps the environment.",yue:"Friends of the Earth（地球之友）係環保慈善機構。"},
{id:228,ch:5,d:2,src:["12.16"],en:"Age UK is a charity that helps elderly people.",yue:"Age UK（英國長者協會）係幫助長者嘅慈善機構。"},
{id:229,ch:5,d:3,src:["9.13"],en:"The NSPCC is the National Society for the Prevention of Cruelty to Children.",yue:"全國防止虐待兒童協會（NSPCC）全名 National Society for the Prevention of Cruelty to Children。"},
{id:230,ch:5,d:1,src:["2.19","7.12","10.22"],en:"The Commonwealth is an association of about 54 countries, mostly from the former British Empire.",yue:"Commonwealth（英聯邦）係約 54 個國家組成嘅組織，大多來自前大英帝國。"},
{id:231,ch:5,d:4,src:["6.23","9.16"],en:"The Council of Europe (47 members, separate from the EU) protects human rights and promotes democracy in Europe.",yue:"Council of Europe（47 個成員國，同歐盟係唔同機構）保障人權、推廣民主。"},
{id:232,ch:5,d:4,src:["8.14","15.18"],en:"The European Convention on Human Rights protects fundamental rights and freedoms; it is enforced by the European Court of Human Rights in Strasbourg.",yue:"歐洲人權公約保障基本權利同自由，由位於 Strasbourg（史特拉斯堡）嘅歐洲人權法院執行。"},
{id:233,ch:5,d:3,src:["3.20","16.0"],y:1945,en:"The United Nations was set up after the Second World War (1945) to prevent war and promote international peace.",yue:"聯合國喺二戰後（1945 年）成立，旨在防止戰爭、促進國際和平。"},
{id:234,ch:5,d:3,src:["10.19"],en:"The UN Security Council maintains international peace and security; the UK is one of its five permanent members.",yue:"聯合國安理會負責維持國際和平同安全，英國係 5 個常任理事國之一。"},
{id:235,ch:5,d:3,src:["15.21"],en:"The UN General Assembly is a forum where all member nations discuss and vote on international issues.",yue:"聯合國大會係所有成員國討論同表決國際議題嘅論壇。"},
{id:236,ch:5,d:3,src:["11.13","16.22"],y:1949,en:"NATO (North Atlantic Treaty Organisation) was founded in 1949; the UK is a founding member committed to collective defence.",yue:"北約（North Atlantic Treaty Organisation, NATO）1949 年成立，英國係創始成員，承諾集體防衛。"},
];
